import React from 'react';
import { Link } from 'react-router-dom';

const Cart = () => {
  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-3xl font-serif font-bold mb-8">Корзина</h1>
      
      <div className="bg-gray-50 p-8 rounded-lg">
        <div className="text-center py-12">
          <div className="text-gray-400 mb-4">
            <svg className="w-16 h-16 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z"></path>
            </svg>
          </div>
          <h3 className="text-xl font-medium mb-4">Ваша корзина пуста</h3>
          <p className="text-gray-600 mb-6">Добавьте товары из каталога, чтобы оформить заказ</p>
          <Link 
            to="/catalog" 
            className="inline-block bg-gold-600 hover:bg-gold-700 text-white px-6 py-3 rounded font-medium transition-colors"
          >
            Перейти в каталог
          </Link>
        </div>
      </div>
    </div>
  );
};

export default Cart;
